const data = $input.first().json.body || $input.first().json;
const current = data.current_usd || 0;
const limit = data.limit_usd || 2.00;
const pct = data.pct || Math.round(current / limit * 100);
const triggered_by = data.triggered_by || 'cost-monitor';

const emoji = pct >= 100 ? '🚨' : pct >= 90 ? '⚠️' : '⚡';
const status = pct >= 100 ? 'LIMIT HIT' : pct >= 90 ? 'CRITICAL' : 'WARNING';

const text = `${emoji} *Cost Alert — ${status}* (${pct}% of daily budget)\n\n*Spend:* $${current.toFixed(4)} / $${limit.toFixed(2)} limit\n*Triggered by:* ${triggered_by}\n\n${pct >= 90 ? '⛔ PAYG models paused. Routing switched to cost_saver.' : '⚙️ Monitor spend closely. Auto-pause at 100%.'}`;

return [{ json: { text, channel: 'C0AEV3MDEDD', pct, current, limit } }];
